// Traduz o payload da Z-API para o formato da nossa RPC.
//
// A Z-API manda MUITA coisa no mesmo webhook: confirmação de entrega, status de
// leitura, presença, e mensagens que NÓS enviamos (fromMe). Sem filtrar, a
// tabela enche de lixo e a conversa fica ilegível.
const b = $input.first().json.body ?? $input.first().json;

const ignorar = (motivo) => [{ json: { processar: false, motivo, bruto_type: b?.type ?? null } }];

if (!b || typeof b !== 'object') return ignorar('payload vazio');
if (b.fromMe === true) return ignorar('mensagem enviada por nos');

// Callbacks de status não têm conteúdo de mensagem.
const temConteudo = b.text || b.image || b.audio || b.video || b.document;
if (!temConteudo) return ignorar('sem conteudo (provavel callback de status)');

let tipo = 'texto';
let texto = null;
let midia = null;

if (b.text) {
  texto = b.text.message ?? null;
} else if (b.image) {
  tipo = 'imagem'; midia = b.image.imageUrl ?? null; texto = b.image.caption ?? null;
} else if (b.audio) {
  tipo = 'audio'; midia = b.audio.audioUrl ?? null;
} else if (b.video) {
  tipo = 'outro'; midia = b.video.videoUrl ?? null; texto = b.video.caption ?? null;
} else if (b.document) {
  tipo = 'documento'; midia = b.document.documentUrl ?? null;
  texto = b.document.fileName ?? null;
}

const telefone = b.phone ?? b.participantPhone ?? null;
if (!telefone) return ignorar('sem telefone');

return [{ json: {
  processar: true,
  p_telefone_raw: String(telefone),
  p_texto: texto,
  p_tipo: tipo,
  p_midia_url: midia,
  p_zapi_message_id: b.messageId ?? b.id ?? null,
} }];
